-- SQL Query to schedule the English Grammar & Error Correction Quiz
DELETE FROM public.quizzes WHERE title = 'English Grammar & Error Correction Challenge';

INSERT INTO public.quizzes (
  title, 
  description, 
  creator_id, 
  is_teacher_quiz, 
  scope, 
  university_id, 
  difficulty, 
  required_inputs, 
  questions, 
  start_time, 
  end_time, 
